from pathlib import Path
p=Path('outputs/index.html');s=p.read_text(encoding='utf-8')
a=s.index('function resolveCombat(){');b=s.index('function checkDeaths(){',a)
new='''function applyBreathCost(p,cost){if(p.shield>0){let absorbed=Math.min(p.shield,cost);p.shield-=absorbed;cost-=absorbed}p.breath-=cost}function awayDirection(p){let others=state.fighters.map(id=>state.players.find(q=>q.id===id)).filter(q=>q&&q.alive&&q.id!==p.id);if(!others.length)return{x:0,y:-1};let t=others.sort((a,b)=>dist(p,a)-dist(p,b))[0],dx=p.x-t.x,dy=p.y-t.y;if(Math.abs(dx)>Math.abs(dy))return{x:Math.sign(dx),y:0};if(dy)return{x:0,y:Math.sign(dy)};return{x:0,y:-1}}function chooseBotCombatActions(){state.fighters.filter(id=>state.players.find(p=>p.id===id)?.bot).forEach(id=>{let p=state.players.find(q=>q.id===id),roll=Math.random();if(roll<.12)state.actions[id]={type:'escape',dir:awayDirection(p),distance:1+Math.floor(Math.random()*3)};else state.actions[id]={type:roll<.34?'block':roll<.78?'attack':'special'}})}function resolveCombat(){if(!host||state.phase!=='combat')return;let fighters=state.fighters.map(id=>state.players.find(p=>p.id===id)).filter(p=>p?.alive),acts={};for(const p of fighters){let raw=state.actions[p.id]||'block';acts[p.id]=typeof raw==='string'?{type:raw}:raw}let damage={};fighters.forEach(p=>damage[p.id]=0);for(const p of fighters){let action=acts[p.id],a=action.type;if(a==='block'||a==='escape')continue;let cost=a==='attack'?3+Math.floor(Math.random()*7):12+Math.floor(Math.random()*7);if(state.momentum===p.id&&state.momentumUsed!==p.id){cost=Math.max(0,cost-3);state.momentumUsed=p.id}applyBreathCost(p,cost);let dealt=a==='attack'?cost*2:cost*2.5;if(state.ambush===p.id&&state.ambushUsed!==p.id){dealt+=5;state.ambushUsed=p.id}for(const t of fighters)if(t.id!==p.id)damage[t.id]+=dealt}let escapes={};for(const p of fighters){let action=acts[p.id];if(action.type!=='escape')continue;let dir=action.dir||awayDirection(p),distance=Math.max(1,Math.min(3,Number(action.distance)||1)),steps=0;for(let k=1;k<=distance;k++){let x=p.x+dir.x*45*k,y=p.y+dir.y*45*k;if(tileBlocked(x,y))break;steps++}escapes[p.id]={dir,steps};applyBreathCost(p,steps*2);if(!steps)log('<b>'+esc(p.name)+'</b> found the route blocked and could not escape.')}fighters.forEach(p=>{let d=damage[p.id];if(acts[p.id].type==='block')d=Math.ceil(d/2);if(p.shield>0){let absorb=Math.min(p.shield,d);p.shield-=absorb;d-=absorb}p.breath-=d});checkDeaths();if(checkWinner())return;for(const p of fighters){let route=escapes[p.id];if(p.alive&&route?.steps){p.x+=route.dir.x*45*route.steps;p.y+=route.dir.y*45*route.steps;log('<b>'+esc(p.name)+'</b> escaped the engagement.')}}let survivors=state.players.filter(p=>p.alive&&!p.contained),pair=findEngagement(survivors);if(pair){state.fighters=pair.ids;state.momentum=pair.initiator;state.ambush=pair.ambush;state.phase='combat';state.combatTurn=(state.combatTurn||1)+1;state.deadline=Date.now()+6000;state.actions={};chooseBotCombatActions();log('Engagement continues. Choose an action or escape route.');sendState();setTimeout(()=>{if(host&&state.phase==='combat')resolveCombat()},6000);return}state.momentum=null;state.ambush=null;state.actions={};log('Engagement ended. Subjects return to the arena.');beginMove();sendState()}'''
s=s[:a]+new+s[b:]
# Trigger bot decisions when combat first starts.
s=s.replace("state.actions[id]=['block','attack','attack','special'][Math.floor(Math.random()*4)]", "state.actions[id]={type:'attack'}",1)
# replace that entire one-time bot assignment with the decision helper
s=s.replace("state.fighters.filter(id=>state.players.find(p=>p.id===id)?.bot).forEach(id=>state.actions[id]={type:'attack'});", "state.actions={};chooseBotCombatActions();",1)
# New action messages are only accepted from current fighters.
s=s.replace("if(m.type==='action'){state.actions[from]=m.action;if(state.fighters.every(id=>state.actions[id]))resolveCombat()}", "if(m.type==='action'&&state.phase==='combat'&&state.fighters.includes(from)){state.actions[from]=m.action;if(state.fighters.every(id=>state.actions[id]))resolveCombat()}")
p.write_text(s,encoding='utf-8')
